-- Fakt kartochkalari orqa tomonining ruscha matni — 71-partiya:
-- O'rol Tansiqboyev, O'tkir Hoshimov, Pahlavon Mahmud.

UPDATE fact_cards SET detail_ru = 'Урал Тансыкбаев родился 14 января 1904 года в Ташкенте. Он остался в истории как живописец-пейзажист и мастер живописи. Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2250;
UPDATE fact_cards SET detail_ru = 'В 1924 году он окончил Пензенское художественное училище. Затем, в 1924–1928 годах, продолжил учение в студии изобразительного искусства при Государственном музее искусств Узбекистана. Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2251;
UPDATE fact_cards SET detail_ru = 'В пору исканий он создал работы «Узбекский портрет» (1927), «Борьба» и «Караван» (1929), «В юрте» (1931). В эту пору он работал в исторических, бытовых и портретных жанрах. Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2252;
UPDATE fact_cards SET detail_ru = 'С 30-х годов главное место в творчестве Тансыкбаева занял пейзаж. «Голубой пейзаж» (1935), «Ночной полив» (1942) — работы этого направления. Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2253;
UPDATE fact_cards SET detail_ru = '«Утро Кайраккумской ГЭС» (1957) — известный образец индустриальных пейзажей Тансыкбаева. Позже в том же направлении созданы работы «На строительстве Чарвака» (1970) и «Голодностепский канал» (1971). Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2254;
UPDATE fact_cards SET detail_ru = 'После войны созданы работы «Горный колхоз» (1949), «Полив хлопчатника» (1949), «Весна в Узбекистане» (1950). Затем явились пейзажи «Родной край» (1951), «Вечер на Иссык-Куле» (1951), «Осень в горах» (1954). Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2255;
UPDATE fact_cards SET detail_ru = 'В 1944 году он получил звание народного художника Узбекистана, а в 1973-м стал лауреатом Государственной премии Узбекистана имени Хамзы. После его смерти, в 2001 году, он был награждён орденом «За великие заслуги». Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2256;
UPDATE fact_cards SET detail_ru = 'Урал Тансыкбаев умер 18 апреля 1974 года. Дом, где он жил в 1967–1974 годах, был в 1981 году обращён в дом-музей; там хранятся его творческая мастерская и известные работы. Источник: Национальная энциклопедия Узбекистана, буква Т (ziyouz.com).' WHERE id = 2257;

UPDATE fact_cards SET detail_ru = 'Уткир Хашимов родился 5 августа 1941 года в ташкентской махалле Домбрабад. Хотя детство его прошло в пору военных тягот и нужды, среднюю школу он окончил на отличные оценки. Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2076;
UPDATE fact_cards SET detail_ru = 'Уткир Хашимов, работая, учился на заочном отделении факультета журналистики Ташкентского государственного университета. Он работал в газетах «Темирйулчи», «Тошкент хакикати», «Кизил Узбекистон», в 1966–1982 годах заведовал отделом в «Тошкент окшоми», в 1982–1985 годах был заместителем главного редактора в издательстве имени Гафура Гуляма, а с 1985 года — главным редактором журнала «Шарк юлдузи». Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2077;
UPDATE fact_cards SET detail_ru = 'Первая книга Уткира Хашимова — «Стальной наездник» — вышла в 1962 году. Сочинений у писателя более пятидесяти, а общий их тираж превышает почти два миллиона. Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2078;
UPDATE fact_cards SET detail_ru = 'Уткир Хашимов создал такие сочинения, как «Весна не возвращается» (1970), «Прислушайся к своему сердцу» (1973), «Где свет, там и тень» (1976), и в 1976 году за эти сочинения был удостоен Республиканской молодёжной премии. Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2079;
UPDATE fact_cards SET detail_ru = 'Повесть «Дела мирские» создана в 1982 году. За это сочинение Уткир Хашимов был награждён премией имени Ойбека Союза писателей Узбекистана. Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2080;
UPDATE fact_cards SET detail_ru = 'Роман «Меж двух дверей» был издан в 1986 году. Этот роман в 1986 году был удостоен Республиканской государственной премии имени Хамзы. Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2081;
UPDATE fact_cards SET detail_ru = 'Книга Уткира Хашимова «Записи на полях тетради» (2001) оставила заметный след в общественной и духовной жизни. Он создал и такие сценические сочинения, как «Увядшая весна», «С праздником свадьбы», «Лекарство совести». Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2082;
UPDATE fact_cards SET detail_ru = 'В 1991 году Уткиру Хашимову было присвоено звание народного писателя Узбекистана. В 1996 году он был награждён орденом «Мехнат шухрати», а в 2001-м — орденом «За великие заслуги». Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2083;
UPDATE fact_cards SET detail_ru = 'Уткир Хашимов умер 24 мая 2013 года в Ташкенте. Источник: Ziyouz.com — раздел «Узбекские просвещённые деятели».' WHERE id = 2084;

UPDATE fact_cards SET detail_ru = 'Пахлаван Махмуд родился в 1247 году. Его жизнь и деятельность связаны с городом Хивой: там он занимался ремеслом и творчеством и возглавлял общину футувват. Источник: Ziyouz.com, статья «Пахлаван Махмуд (1247–1326)».' WHERE id = 1960;
UPDATE fact_cards SET detail_ru = 'За богатые и глубокие по смыслу, крепкие по форме философские рубаи Пахлаван Махмуд снискал славу под именем «Хайям Хорезма». Учёный Н. Комилов разделил его рубаи на четыре группы: сетование на людей своего времени, следование по пути тариката, философия единства бытия и темы божественной любви. Источник: Ziyouz.com, статья «Пахлаван Махмуд (1247–1326)».' WHERE id = 1961;
UPDATE fact_cards SET detail_ru = 'Пахлаван Махмуд участвовал в состязаниях по борьбе в Иране, Индии и других странах Востока и всегда одерживал победу. За всю жизнь его лопатки не коснулись земли — он считался первым борцом страны и вождём борцов. Источник: Ziyouz.com, статья «Пахлаван Махмуд (1247–1326)».' WHERE id = 1962;
UPDATE fact_cards SET detail_ru = 'Пахлаван Махмуд занимался ремеслом скорняка — шил тулупы. По его завещанию ученики погребли его подле его же скорняжной лавки. Источник: Ziyouz.com, статья «Пахлаван Махмуд (1247–1326)».' WHERE id = 1963;
UPDATE fact_cards SET detail_ru = 'Во многих источниках говорится, что у Пахлавана Махмуда есть маснави под названием «Канз уль-хакоик» («Сокровищница истин»); в 1967 году иранский учёный Саид Мухаммад Али Сафир издал это сочинение, приписав его Махмуду Шабустари. Пахлаван Махмуд написал и несколько трактатов по богословию, философии и логике, однако эти трактаты до сих пор не найдены. Источник: Ziyouz.com, статья «Пахлаван Махмуд (1247–1326)».' WHERE id = 1964;
UPDATE fact_cards SET detail_ru = 'Пахлаван Махмуд был главой общины футувват в Хиве, вождём джаванмардов. Девизом джаванмардов было всегда и повсюду защищать, проповедовать и поддерживать добро против всех обличий зла в мире; он являл высшие образцы мужества и щедрости и был примером для других. Источник: Ziyouz.com, статья «Пахлаван Махмуд (1247–1326)».' WHERE id = 1965;
UPDATE fact_cards SET detail_ru = 'Пахлаван Махмуд умер в 1326 году. По его завещанию ученики погребли его подле его скорняжной лавки; позже над могилой был возведён мавзолей, а у его подножия погребены хивинские ханы из рода Кунграт. На стенах мавзолея начертаны рубаи поэта, и его посещают паломники из разных уголков мира. Источник: Ziyouz.com, статья «Пахлаван Махмуд (1247–1326)».' WHERE id = 1966;
